import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useProperty } from '../contexts/PropertyContext';
import { useSearchParams } from 'react-router-dom';
import AddPropertyModal from '../components/Property/AddPropertyModal';

const LandlordDashboard = () => {
  const { user, isAuthenticated } = useAuth();
  const { properties, fetchProperties, loading } = useProperty();
  const [searchParams, setSearchParams] = useSearchParams();
  const [activeTab, setActiveTab] = useState('overview');
  const [isAddPropertyModalOpen, setIsAddPropertyModalOpen] = useState(false);

  // Handle URL parameters on component mount
  useEffect(() => {
    const tab = searchParams.get('tab');
    const action = searchParams.get('action');
    
    // Set active tab if specified
    if (tab) {
      setActiveTab(tab);
    }
    
    // Open add property modal if action=add
    if (action === 'add') {
      setIsAddPropertyModalOpen(true);
      // Clean up the URL parameters
      const newParams = new URLSearchParams(searchParams);
      newParams.delete('action');
      setSearchParams(newParams, { replace: true });
    }
  }, [searchParams, setSearchParams]);

  // Fetch properties when component mounts
  useEffect(() => {
    if (isAuthenticated) {
      console.log('🏠 LandlordDashboard: Fetching properties...');
      fetchProperties();
    }
  }, [isAuthenticated, fetchProperties]);

  // Properties now come from PropertyContext

  const tabs = [
    { id: 'overview', name: 'Overview', icon: '📊' },
    { id: 'properties', name: 'Properties', icon: '🏠' },
    { id: 'tenants', name: 'Tenants', icon: '👥' },
    { id: 'finances', name: 'Finances', icon: '💰' },
    { id: 'messages', name: 'Messages', icon: '💬' },
  ];

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="text-center">
          <div className="text-6xl mb-4">🔐</div>
          <h1 className="text-2xl font-bold text-gray-900 mb-4">
            Please Login
          </h1>
          <p className="text-gray-600 mb-6">
            You need to be logged in to access the dashboard.
          </p>
          <button className="btn btn-primary">
            Login
          </button>
        </div>
      </div>
    );
  }

  const renderOverview = () => (
    <div className="space-y-6">
      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="bg-white rounded-lg shadow-sm p-6">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-600">Total Properties</p>
              <p className="text-3xl font-bold text-gray-900">12</p>
            </div>
            <div className="text-2xl">🏠</div>
          </div>
        </div>
        <div className="bg-white rounded-lg shadow-sm p-6">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-600">Occupied</p>
              <p className="text-3xl font-bold text-green-600">8</p>
            </div>
            <div className="text-2xl">✅</div>
          </div>
        </div>
        <div className="bg-white rounded-lg shadow-sm p-6">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-600">Available</p>
              <p className="text-3xl font-bold text-blue-600">4</p>
            </div>
            <div className="text-2xl">🔓</div>
          </div>
        </div>
        <div className="bg-white rounded-lg shadow-sm p-6">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-600">Monthly Income</p>
              <p className="text-3xl font-bold text-primary-600">$18K</p>
            </div>
            <div className="text-2xl">💰</div>
          </div>
        </div>
      </div>

      {/* Recent Activity */}
      <div className="bg-white rounded-lg shadow-sm p-6">
        <h3 className="text-lg font-semibold text-gray-900 mb-4">Recent Activity</h3>
        <div className="space-y-4">
          <div className="flex items-center p-3 bg-gray-50 rounded-lg">
            <div className="w-10 h-10 bg-green-100 rounded-full flex items-center justify-center mr-3">
              <svg className="w-5 h-5 text-green-600" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
              </svg>
            </div>
            <div>
              <p className="font-medium text-gray-900">New lease signed for Downtown Apartment</p>
              <p className="text-sm text-gray-600">2 hours ago</p>
            </div>
          </div>
          <div className="flex items-center p-3 bg-gray-50 rounded-lg">
            <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center mr-3">
              <svg className="w-5 h-5 text-blue-600" fill="currentColor" viewBox="0 0 20 20">
                <path d="M2.003 5.884L10 9.882l7.997-3.998A2 2 0 0016 4H4a2 2 0 00-1.997 1.884z" />
                <path d="M18 8.118l-8 4-8-4V14a2 2 0 002 2h12a2 2 0 002-2V8.118z" />
              </svg>
            </div>
            <div>
              <p className="font-medium text-gray-900">New inquiry for Suburban House</p>
              <p className="text-sm text-gray-600">1 day ago</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );

  const renderProperties = () => (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-gray-900">My Properties</h2>
        <button 
          onClick={() => setIsAddPropertyModalOpen(true)}
          className="btn btn-primary"
        >
          + Add Property
        </button>
      </div>
      
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {loading ? (
          <div className="col-span-full text-center py-8 text-gray-500">
            <p>Loading properties...</p>
          </div>
        ) : properties.length === 0 ? (
          <div className="col-span-full text-center py-8 text-gray-500">
            <div className="text-4xl mb-4">🏠</div>
            <p className="text-lg font-medium mb-2">No properties yet</p>
            <p className="text-sm mb-4">Add your first property to get started!</p>
            <button 
              onClick={() => setIsAddPropertyModalOpen(true)}
              className="btn btn-primary"
            >
              + Add First Property
            </button>
          </div>
        ) : properties.map((property) => (
          <div key={property._id} className="bg-white rounded-lg shadow-sm overflow-hidden">
            <img
              src={property.images?.[0] || 'https://images.unsplash.com/photo-1497366216548-37526070297c?w=800'}
              alt={property.title}
              className="w-full h-48 object-cover"
            />
            <div className="p-4">
              <h3 className="font-semibold text-gray-900 mb-2">{property.title}</h3>
              <p className="text-gray-600 text-sm mb-2">
                {property.address?.area}, {property.address?.city}
              </p>
              <div className="flex justify-between items-center mb-3">
                <span className="text-lg font-bold text-gray-900">
                  ₹{property.rental?.monthlyRent?.toLocaleString()}/month
                </span>
                <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                  property.status === 'rented' 
                    ? 'bg-green-100 text-green-800' 
                    : 'bg-blue-100 text-blue-800'
                }`}>
                  {property.status === 'rented' ? 'Rented' : 'Available'}
                </span>
              </div>
              <div className="text-sm text-gray-600 mb-3">
                <p>{property.propertyType} • {property.specifications?.totalArea} sq ft</p>
              </div>
              <div className="flex space-x-2">
                <button className="btn btn-secondary text-xs px-3 py-1">
                  Edit
                </button>
                <button className="btn bg-red-100 text-red-700 hover:bg-red-200 text-xs px-3 py-1">
                  Delete
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );

  const renderContent = () => {
    switch (activeTab) {
      case 'overview':
        return renderOverview();
      case 'properties':
        return renderProperties();
      case 'tenants':
      case 'finances':
      case 'messages':
        return (
          <div className="text-center py-12">
            <div className="text-6xl mb-4">🚧</div>
            <h3 className="text-xl font-semibold text-gray-900 mb-2">
              Coming Soon
            </h3>
            <p className="text-gray-600">
              This section is currently under development.
            </p>
          </div>
        );
      default:
        return renderOverview();
    }
  };

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        {/* Header */}
        <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-2xl font-bold text-gray-900">
                Welcome back, {user?.name || 'Landlord'}!
              </h1>
              <p className="text-gray-600">
                Manage your properties and track your rental business.
              </p>
            </div>
            <div className="text-4xl">👋</div>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
          {/* Sidebar */}
          <div className="lg:col-span-1">
            <div className="bg-white rounded-lg shadow-sm p-4">
              <nav className="space-y-2">
                {tabs.map((tab) => (
                  <button
                    key={tab.id}
                    onClick={() => setActiveTab(tab.id)}
                    className={`w-full text-left px-4 py-3 rounded-lg transition-colors flex items-center ${
                      activeTab === tab.id
                        ? 'bg-primary-50 text-primary-600 border border-primary-200'
                        : 'text-gray-700 hover:bg-gray-50'
                    }`}
                  >
                    <span className="mr-3">{tab.icon}</span>
                    {tab.name}
                  </button>
                ))}
              </nav>
            </div>
          </div>

          {/* Main Content */}
          <div className="lg:col-span-3">
            {renderContent()}
          </div>
        </div>

        {/* Add Property Modal */}
        <AddPropertyModal
          isOpen={isAddPropertyModalOpen}
          onClose={() => setIsAddPropertyModalOpen(false)}
        />
      </div>
    </div>
  );
};

export default LandlordDashboard;
